initJs:
function(container, apiUrl, tables) {
  // 業務ロジックのインポート
  const {
    collectSalesData,
    classifySalesDataByProduct,
    classifySalesDataByStore,
    filterValidProductData,
    collectWeatherData,
    collectEventData,
    collectSeasonalData,
    analyzeCorrelationSalesWeather,
    analyzeCorrelationSalesEvent,
    analyzeCorrelationSalesSeason,
    compareWithHistoricalData,
    findAlternativeComparisonData,
    validateComparisonPeriod
  } = window.aiLogic || {};

  let currentProducts = [];
  let currentForecast = {};

  // エラー表示関数
  function showError(message) {
    window.aivicNotify.error(message);
    const errorDiv = container.querySelector('#error-message');
    if (errorDiv) {
      errorDiv.textContent = message;
      errorDiv.classList.remove('hidden');
      setTimeout(() => errorDiv.classList.add('hidden'), 5000);
    }
  }

  // 成功表示関数
  function showSuccess(message) {
    window.aivicNotify.success(message);
  }

  // バリデーション関数
  function validateInputs() {
    const storeId = container.querySelector('#select-store').value;
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (!startDate || !endDate) {
      showError('対象期間を設定してください');
      return false;
    }

    // 期間バリデーション（業務ロジック使用）
    if (validateComparisonPeriod) {
      const validation = validateComparisonPeriod(startDate, endDate);
      if (!validation.valid) {
        showError(validation.message);
        return false;
      }
    }

    return true;
  }

  // 数値バリデーション関数
  function validateNumber(value, fieldName, min = 0, max = null) {
    if (value === '' || value === null || value === undefined) return true;

    const num = parseFloat(value);
    if (isNaN(num)) {
      showError(`${fieldName}は数値を入力してください`);
      return false;
    }

    if (num < min) {
      showError(`${fieldName}は${min}以上の値を入力してください`);
      return false;
    }

    if (max !== null && num > max) {
      showError(`${fieldName}は${max}以下の値を入力してください`);
      return false;
    }

    return true;
  }

  // 店舗データ読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (!stores) return;

      const select = container.querySelector('#select-store');
      if (!select) return;

      select.innerHTML = '<option value="">店舗を選択してください</option>';

      stores.filter(store => store.有効フラグ).forEach(store => {
        const option = document.createElement('option');
        option.value = store.店舗ID;
        option.textContent = `${store.店舗コード} - ${store.店舗名}`;
        select.appendChild(option);
      });
    } catch (error) {
      showError('店舗データの読み込みに失敗しました');
    }
  }

  // 商品検索・絞り込み
  async function searchProducts() {
    try {
      const keyword = container.querySelector('#input-search')?.value.trim() || '';
      const categoryId = container.querySelector('#select-category')?.value || '';

      const products = await window.aivicApi.list(2); // 商品マスタ
      if (!products) return;

      let filteredProducts = products.filter(product => product.有効フラグ);

      if (keyword) {
        filteredProducts = filteredProducts.filter(product => 
          product.商品名.includes(keyword) || 
          product.商品コード.includes(keyword)
        );
      }

      if (categoryId) {
        filteredProducts = filteredProducts.filter(product => 
          product.カテゴリID === categoryId
        );
      }

      currentProducts = filteredProducts;
      displayProducts(filteredProducts);
    } catch (error) {
      showError('商品検索に失敗しました');
    }
  }

  // 商品一覧表示
  function displayProducts(products) {
    const tbody = container.querySelector('#products-table tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    products.forEach(product => {
      const row = document.createElement('tr');
      row.innerHTML = `
        <td>
          <input type="checkbox" class="product-checkbox" value="${product.商品ID}">
        </td>
        <td>${product.商品コード}</td>
        <td>${product.商品名}</td>
        <td>${product.カテゴリ名 || ''}</td>
        <td>${product.単価 || 0}</td>
        <td>${product.在庫数量 || 0}</td>
      `;
      tbody.appendChild(row);
    });
  }

  // 需要予測実行
  async function executeForecast() {
    if (!validateInputs()) return;

    try {
      const storeId = container.querySelector('#select-store').value;
      const startDate = container.querySelector('#input-start-date').value;
      const endDate = container.querySelector('#input-end-date').value;

      // 選択された商品を取得
      const selectedProductIds = Array.from(
        container.querySelectorAll('.product-checkbox:checked')
      ).map(cb => cb.value);

      if (selectedProductIds.length === 0) {
        showError('商品を選択してください');
        return;
      }

      // 売上データ収集
      const salesData = await collectSalesData(storeId, startDate, endDate);
      if (!salesData || salesData.length === 0) {
        showError('売上データが見つかりません');
        return;
      }

      // 商品別売上データ分類
      const productSalesData = classifySalesDataByProduct(salesData, selectedProductIds);

      // 有効な商品データのフィルタリング
      const validProductData = filterValidProductData(productSalesData);

      // 外部要因データ収集
      const weatherData = await collectWeatherData(startDate, endDate);
      const eventData = await collectEventData(startDate, endDate);
      const seasonalData = collectSeasonalData(startDate, endDate);

      // 相関分析
      const weatherCorrelation = analyzeCorrelationSalesWeather(validProductData, weatherData);
      const eventCorrelation = analyzeCorrelationSalesEvent(validProductData, eventData);
      const seasonalCorrelation = analyzeCorrelationSalesSeason(validProductData, seasonalData);

      // 過去データとの比較
      const historicalComparison = await compareWithHistoricalData(validProductData, storeId);

      // 予測結果の生成
      const forecastResult = generateForecastResult(
        validProductData,
        weatherCorrelation,
        eventCorrelation,
        seasonalCorrelation,
        historicalComparison
      );

      currentForecast = forecastResult;
      displayForecastResult(forecastResult);
      showSuccess('需要予測が完了しました');

    } catch (error) {
      console.error('Forecast error:', error);
      showError('需要予測の実行に失敗しました');
    }
  }

  // 予測結果生成（簡易版）
  function generateForecastResult(productData, weatherCorr, eventCorr, seasonalCorr, historical) {
    const result = {};

    Object.keys(productData).forEach(productId => {
      const baseQuantity = productData[productId].averageQuantity || 0;
      const weatherFactor = weatherCorr[productId]?.factor || 1.0;
      const eventFactor = eventCorr[productId]?.factor || 1.0;
      const seasonalFactor = seasonalCorr[productId]?.factor || 1.0;
      const historicalFactor = historical[productId]?.factor || 1.0;

      const predictedQuantity = Math.round(
        baseQuantity * weatherFactor * eventFactor * seasonalFactor * historicalFactor
      );

      result[productId] = {
        predictedQuantity,
        confidence: calculateConfidence(weatherCorr[productId], eventCorr[productId], seasonalCorr[productId]),
        factors: {
          weather: weatherFactor,
          event: eventFactor,
          seasonal: seasonalFactor,
          historical: historicalFactor
        }
      };
    });

    return result;
  }

  // 信頼度計算
  function calculateConfidence(weatherCorr, eventCorr, seasonalCorr) {
    const baseConfidence = 0.7;
    const weatherBonus = weatherCorr?.correlation > 0.5 ? 0.1 : 0;
    const eventBonus = eventCorr?.correlation > 0.5 ? 0.1 : 0;
    const seasonalBonus = seasonalCorr?.correlation > 0.5 ? 0.1 : 0;

    return Math.min(baseConfidence + weatherBonus + eventBonus + seasonalBonus, 1.0);
  }

  // 予測結果表示
  function displayForecastResult(forecast) {
    const tbody = container.querySelector('#forecast-table tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    Object.keys(forecast).forEach(productId => {
      const product = currentProducts.find(p => p.商品ID === productId);
      const prediction = forecast[productId];

      if (!product) return;

      const row = document.createElement('tr');
      row.innerHTML = `
        <td>${product.商品コード}</td>
        <td>${product.商品名}</td>
        <td>${prediction.predictedQuantity}</td>
        <td>${Math.round(prediction.confidence * 100)}%</td>
        <td>
          <input type="number" class="order-quantity" 
                 data-product-id="${productId}" 
                 value="${prediction.predictedQuantity}" 
                 min="0" step="1">
        </td>
        <td>
          <button class="btn-adjust" data-product-id="${productId}">調整</button>
        </td>
      `;
      tbody.appendChild(row);
    });

    // 調整ボタンのイベントリスナー
    container.querySelectorAll('.btn-adjust').forEach(btn => {
      btn.addEventListener('click', handleQuantityAdjust);
    });
  }

  // 発注量調整
  function handleQuantityAdjust(event) {
    const productId = event.target.dataset.productId;
    const input = container.querySelector(`input[data-product-id="${productId}"]`);

    if (!input) return;

    const quantity = parseInt(input.value);
    if (!validateNumber(quantity, '発注量', 0)) return;

    // 調整理由の入力（簡易版）
    const reason = prompt('調整理由を入力してください（任意）:');

    // 調整履歴の記録
    if (!currentForecast[productId].adjustments) {
      currentForecast[productId].adjustments = [];
    }

    currentForecast[productId].adjustments.push({
      originalQuantity: currentForecast[productId].predictedQuantity,
      adjustedQuantity: quantity,
      reason: reason || '',
      timestamp: new Date().toISOString()
    });

    currentForecast[productId].finalQuantity = quantity;
    showSuccess('発注量を調整しました');
  }

  // 発注データ保存
  async function saveOrderData() {
    if (!currentForecast || Object.keys(currentForecast).length === 0) {
      showError('予測データがありません');
      return;
    }

    try {
      const storeId = container.querySelector('#select-store').value;
      const orderDate = new Date().toISOString().split('T')[0];

      const orderData = Object.keys(currentForecast).map(productId => {
        const forecast = currentForecast[productId];
        const product = currentProducts.find(p => p.商品ID === productId);

        return {
          店舗ID: storeId,
          商品ID: productId,
          商品コード: product?.商品コード,
          商品名: product?.商品名,
          予測数量: forecast.predictedQuantity,
          発注数量: forecast.finalQuantity || forecast.predictedQuantity,
          信頼度: forecast.confidence,
          発注日: orderDate,
          ステータス: '予測完了',
          調整履歴: JSON.stringify(forecast.adjustments || [])
        };
      });

      // 発注データテーブルに保存
      for (const order of orderData) {
        await window.aivicApi.save(5, order); // 発注データテーブル
      }

      showSuccess('発注データを保存しました');

      // 保存後の画面更新
      displaySavedOrders(orderData);

    } catch (error) {
      console.error('Save error:', error);
      showError('発注データの保存に失敗しました');
    }
  }

  // 保存済み発注データ表示
  function displaySavedOrders(orders) {
    const tbody = container.querySelector('#saved-orders-table tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    orders.forEach(order => {
      const row = document.createElement('tr');
      row.innerHTML = `
        <td>${order.商品コード}</td>
        <td>${order.商品名}</td>
        <td>${order.予測数量}</td>
        <td>${order.発注数量}</td>
        <td>${Math.round(order.信頼度 * 100)}%</td>
        <td>${order.ステータス}</td>
        <td>${order.発注日}</td>
      `;
      tbody.appendChild(row);
    });
  }

  // カテゴリデータ読み込み
  async function loadCategories() {
    try {
      const categories = await window.aivicApi.list(3); // カテゴリマスタ
      if (!categories) return;

      const select = container.querySelector('#select-category');
      if (!select) return;

      select.innerHTML = '<option value="">全カテゴリ</option>';

      categories.forEach(category => {
        const option = document.createElement('option');
        option.value = category.カテゴリID;
        option.textContent = category.カテゴリ名;
        select.appendChild(option);
      });
    } catch (error) {
      showError('カテゴリデータの読み込みに失敗しました');
    }
  }

  // イベントリスナーの設定
  function setupEventListeners() {
    // 検索ボタン
    const searchBtn = container.querySelector('#btn-search');
    if (searchBtn) {
      searchBtn.addEventListener('click', searchProducts);
    }

    // 予測実行ボタン
    const forecastBtn = container.querySelector('#btn-forecast');
    if (forecastBtn) {
      forecastBtn.addEventListener('click', executeForecast);
    }

    // 保存ボタン
    const saveBtn = container.querySelector('#btn-save');
    if (saveBtn) {
      saveBtn.addEventListener('click', saveOrderData);
    }

    // 全選択チェックボックス
    const selectAllBtn = container.querySelector('#btn-select-all');
    if (selectAllBtn) {
      selectAllBtn.addEventListener('click', () => {
        const checkboxes = container.querySelectorAll('.product-checkbox');
        checkboxes.forEach(cb => cb.checked = true);
      });
    }

    // 全解除ボタン
    const deselectAllBtn = container.querySelector('#btn-deselect-all');
    if (deselectAllBtn) {
      deselectAllBtn.addEventListener('click', () => {
        const checkboxes = container.querySelectorAll('.product-checkbox');
        checkboxes.forEach(cb => cb.checked = false);
      });
    }

    // カテゴリ変更時の自動検索
    const categorySelect = container.querySelector('#select-category');
    if (categorySelect) {
      categorySelect.addEventListener('change', searchProducts);
    }

    // Enterキーでの検索
    const searchInput = container.querySelector('#input-search');
    if (searchInput) {
      searchInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') {
          searchProducts();
        }
      });
    }
  }

  // 初期化処理
  async function initialize() {
    try {
      // 初期データ読み込み
      await loadStores();
      await loadCategories();

      // イベントリスナー設定
      setupEventListeners();

      // デフォルト日付設定
      const today = new Date();
      const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);

      const startDateInput = container.querySelector('#input-start-date');
      const endDateInput = container.querySelector('#input-end-date');

      if (startDateInput) {
        startDateInput.value = today.toISOString().split('T')[0];
      }
      if (endDateInput) {
        endDateInput.value = nextWeek.toISOString().split('T')[0];
      }

      // 初期商品検索
      await searchProducts();

    } catch (error) {
      console.error('Initialization error:', error);
      showError('画面の初期化に失敗しました');
    }
  }

  // 初期化実行
  initialize();
}
